Dùng tìm kiếm nhị phân trên dãy đã sắp xếp gồm 15 phần tử, trong trường hợp xấu nhất cần tối đa bao nhiêu lần so sánh với phần tử giữa?
def tim(A, x):
    l, r = 0, len(A) - 1
    dem = 0
    while l <= r:
        m = (l + r) // 2
        dem += 1
        if A[m] == x:
            return dem
        elif A[m] < x:
            l = m + 1
        else:
            r = m - 1
    return -1
A = list(range(15))
print(max(tim(A, x) for x in A))

Sắp xếp dãy [4, 3, 2, 1] tăng dần bằng thuật toán nổi bọt. Tổng số lần đổi chỗ hai phần tử là
A = [4, 3, 2, 1]
d = 0
n = len(A)
for i in range(n - 1):
    for j in range(n - 1 - i):
        if A[j] > A[j + 1]:
            A[j], A[j + 1] = A[j + 1], A[j]
            d += 1
print(d)

Cho đoạn chương trình:
def tim(A, x):
    for i in range(len(A)):
        if A[i] == x:
            return i
    return -1

print(tim([4, 7, 1, 9, 2, 9], 9))
