Cho hàm tìm kiếm nhị phân (dem là số lần lặp) và dãy A = [3, 8, 15, 21, 30, 42, 57]:
def tim(A, x):
    l, r = 0, len(A) - 1
    dem = 0
    while l <= r:
        m = (l + r) // 2
        dem += 1
        if A[m] == x:
            return dem
        elif A[m] < x:
            l = m + 1
        else:
            r = m - 1
    return -1
